def verify():
    z, wn = 0.6, 5.0
    assert abs(6 / (2 * wn) - z) < 1e-12
    assert abs(math.exp(-math.pi * z / math.sqrt(1 - z * z)) * 100 - 9.48) < 0.01 and abs(4 / (z * wn) - 1.333) < 0.001
    assert abs(10 / 11 - 0.909) < 0.001 and abs(4 / 3 - 1.333) < 0.001
    import numpy as np
    r = np.roots([1, 1, 2, 8]); assert sum(1 for x in r if x.real > 0) == 2
    for K, ok in ((5.9, True), (6.1, False)):
        assert (max(x.real for x in np.roots([1, 2, 3, K])) < 0) == ok
    r = np.roots([1, 6, 8, 48]); assert min(abs(x.real) for x in r) < 1e-9
    assert abs(cmath.phase(1 / (1j + 1)) * 180 / math.pi + 45) < 1e-9 and abs(20 * math.log10(4) - 12.04) < 0.01
    assert sorted(np.linalg.eigvals(np.array([[0, 1], [-6, -5]])).real.round(9)) == [-3, -2]


if __name__ == "__main__":
    verify()
    write_subject(SUBJECT, U)
